Rules.InvariantScript:
If(
    ThisItem.TipoNotifica.Value = "RichiestaDistaccoCliente",
    Patch(
        'Clienti-BC',
        LookUp('Clienti-BC', ID = Value(ThisItem.LinkRif)),
        { 'Cod agente': Blank() }
    );
    Patch('Notifiche-BC', ThisItem, { Letta: true, 'Approvata\Rifiutata': { Value: "Approvata" } });
    Notify("Cliente staccato dall'agente", NotificationType.Success),

    ThisItem.TipoNotifica.Value = "RichiestaEliminazioneCliente",
    Patch(
        'Clienti-BC',
        LookUp('Clienti-BC', ID = Value(ThisItem.LinkRif)),
        { Attivo: false }
    );
    Patch('Notifiche-BC', ThisItem, { Letta: true, 'Approvata\Rifiutata': { Value: "Approvata" } });
    Notify("Cliente disattivato", NotificationType.Success),

    ThisItem.TipoNotifica.Value = "RichiestaRiordino",
    With(
        { riordinoSel: LookUp('Riordini-BC', ID = Value(ThisItem.LinkRif)) },
        With(
            { articoloSel: LookUp('Articoli-BC', Nr = riordinoSel.CodArticolo) },
            With(
                { nuovaQta: Value(articoloSel.'Quantità residua') + Value(riordinoSel.QtaRichiesta) },
                Patch('Articoli-BC', articoloSel, { 'Quantità residua': nuovaQta });
                Patch('Riordini-BC', riordinoSel, { Stato: { Value: "Approvato" } });
                Patch('Notifiche-BC', ThisItem, { Letta: true, 'Approvata\Rifiutata': { Value: "Approvata" } });
                Notify("Riordino approvato ✔ Nuova quantità: " & nuovaQta, NotificationType.Success)
            )
        )
    ),

    // altri tipi (fallback)
    Patch('Notifiche-BC', ThisItem, { Letta: true });
    Notify("Notifica letta", NotificationType.Success)
)

If(
    ThisItem.TipoNotifica.Value = "RichiestaRiordino",
    Patch(
        'Riordini-BC',
        LookUp('Riordini-BC', ID = Value(ThisItem.LinkRif)),
        { Stato: { Value: "Rifiutato" } }
    );
    true
);
Patch(
    'Notifiche-BC',
    ThisItem,
    {
        Letta: true,
        'Approvata\Rifiutata': { Value: "Rifiutata" }
    }
);
Notify("Richiesta rifiutata", NotificationType.Success)

Set(varClienteSel, LookUp('Clienti-BC', ID = Value(ThisItem.LinkRif)));
Set(varPopupNotifiche, false);
Set(varPopupCliente, true);
Navigate(scrCustomers)

ControlPropertyState.AutoRuleBindingString:
Patch(
    'Notifiche-BC',
    ThisItem,
    {
        Letta: true,
        'Approvata\Rifiutata': { Value: "Rifiutata" }
    }
);
Notify("Richiesta rifiutata", NotificationType.Success)

